/**
 * One named circuit input and its values. Array signals are flattened under
 * the array's name (`"v"`, not `"v[0]"`). Each value is a canonical decimal
 * string below the BN254 scalar field modulus.
 */
public struct CircuitInput {
    public var name: String
    public var values: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(name: String, values: [String]) {
        self.name = name
        self.values = values
    }
}



extension CircuitInput: Equatable, Hashable {
    public static func ==(lhs: CircuitInput, rhs: CircuitInput) -> Bool {
        if lhs.name != rhs.name {
            return false
        }
        if lhs.values != rhs.values {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(name)
        hasher.combine(values)
    }
}


