/**
 * A Groth16 proof and the public signals it was generated for.
 */
public struct ProofResult {
    /**
     * The proof in snarkjs `proof.json` layout.
     */
    public var proofJson: String
    /**
     * Public signals as canonical decimal strings, outputs first and then
     * public inputs. A valid proof does not say the application condition
     * holds: for age_check, read `public_signals[0]` (`out`) yourself.
     */
    public var publicSignals: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The proof in snarkjs `proof.json` layout.
         */proofJson: String, 
        /**
         * Public signals as canonical decimal strings, outputs first and then
         * public inputs. A valid proof does not say the application condition
         * holds: for age_check, read `public_signals[0]` (`out`) yourself.
         */publicSignals: [String]) {
        self.proofJson = proofJson
        self.publicSignals = publicSignals
    }
}



extension ProofResult: Equatable, Hashable {
    public static func ==(lhs: ProofResult, rhs: ProofResult) -> Bool {
        if lhs.proofJson != rhs.proofJson {
            return false
        }
        if lhs.publicSignals != rhs.publicSignals {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(proofJson)
        hasher.combine(publicSignals)
    }
}


