public enum ProverError {

    
    
    /**
     * An input value is not a canonical decimal below the BN254 scalar modulus.
     * `value` is truncated.
     */
    case InvalidInputValue(signal: String, index: UInt32, value: String
    )
    case UnknownSignal(name: String
    )
    case DuplicateSignal(name: String
    )
    case InputSize(signal: String, expected: UInt64, got: UInt64
    )
    case MissingInputs(set: UInt64, expected: UInt64
    )
    /**
     * The circuit rejected the inputs (a failed `assert` or `===`).
     */
    case AssertionFailed(detail: String
    )
    /**
     * The circuit's module could not get the memory it needed.
     */
    case ResourceExhausted(detail: String
    )
    /**
     * Any other Circom exception, with Circom's code. Not necessarily bad input.
     */
    case CircuitAbort(code: Int32, reason: String, detail: String
    )
    /**
     * The witness engine failed (not a Circom exception).
     */
    case WitnessEngine(detail: String
    )
    case ArtifactLoad(detail: String
    )
    case InvalidArtifact(detail: String
    )
    /**
     * The artifact has a Laniakea header with a format version this SDK does not
     * read (typically an artifact newer than the SDK).
     */
    case UnsupportedArtifactVersion(found: UInt32, supported: UInt32
    )
    case InvalidCircuitModule(detail: String
    )
    case UnsupportedField(detail: String
    )
    case CircuitEngine(detail: String
    )
    case InvalidWitness(detail: String
    )
    case ProofGeneration(detail: String
    )
    /**
     * Anything not covered above: errors that `prove` cannot currently produce
     * (verification, JSON, curve points) and variants added to the core later.
     * A bug or a version mismatch, never the caller's input.
     */
    case Internal(detail: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeProverError: FfiConverterRustBuffer {
    typealias SwiftType = ProverError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ProverError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInputValue(
            signal: try FfiConverterString.read(from: &buf), 
            index: try FfiConverterUInt32.read(from: &buf), 
            value: try FfiConverterString.read(from: &buf)
            )
        case 2: return .UnknownSignal(
            name: try FfiConverterString.read(from: &buf)
            )
        case 3: return .DuplicateSignal(
            name: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InputSize(
            signal: try FfiConverterString.read(from: &buf), 
            expected: try FfiConverterUInt64.read(from: &buf), 
            got: try FfiConverterUInt64.read(from: &buf)
            )
        case 5: return .MissingInputs(
            set: try FfiConverterUInt64.read(from: &buf), 
            expected: try FfiConverterUInt64.read(from: &buf)
            )
        case 6: return .AssertionFailed(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .ResourceExhausted(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .CircuitAbort(
            code: try FfiConverterInt32.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .WitnessEngine(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 10: return .ArtifactLoad(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 11: return .InvalidArtifact(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 12: return .UnsupportedArtifactVersion(
            found: try FfiConverterUInt32.read(from: &buf), 
            supported: try FfiConverterUInt32.read(from: &buf)
            )
        case 13: return .InvalidCircuitModule(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 14: return .UnsupportedField(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 15: return .CircuitEngine(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 16: return .InvalidWitness(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 17: return .ProofGeneration(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 18: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ProverError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInputValue(signal,index,value):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(signal, into: &buf)
            FfiConverterUInt32.write(index, into: &buf)
            FfiConverterString.write(value, into: &buf)
            
        
        case let .UnknownSignal(name):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .DuplicateSignal(name):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(name, into: &buf)
            
        
        case let .InputSize(signal,expected,got):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(signal, into: &buf)
            FfiConverterUInt64.write(expected, into: &buf)
            FfiConverterUInt64.write(got, into: &buf)
            
        
        case let .MissingInputs(set,expected):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(set, into: &buf)
            FfiConverterUInt64.write(expected, into: &buf)
            
        
        case let .AssertionFailed(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ResourceExhausted(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .CircuitAbort(code,reason,detail):
            writeInt(&buf, Int32(8))
            FfiConverterInt32.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .WitnessEngine(detail):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ArtifactLoad(detail):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidArtifact(detail):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .UnsupportedArtifactVersion(found,supported):
            writeInt(&buf, Int32(12))
            FfiConverterUInt32.write(found, into: &buf)
            FfiConverterUInt32.write(supported, into: &buf)
            
        
        case let .InvalidCircuitModule(detail):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .UnsupportedField(detail):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .CircuitEngine(detail):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidWitness(detail):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ProofGeneration(detail):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Internal(detail):
            writeInt(&buf, Int32(18))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


